/* 커스터마이즈 원본 16개와 4색 팔레트 64개를 통합한 데이터입니다.
   색상·투명도·크기는 원본 그대로 보존합니다. 생성: work/build-customize-bundle.cjs */
(() => {
 const packed='';
 const cache=new Map();let entries,data,start;
 const keys=['pink','yellow','green','blue'];
 const api={
  has(file){return Boolean(entries?.has(file));},
  get(file,color=null){
   const key=file+':'+(color===null?'original':color);
   if(cache.has(key))return cache.get(key);
   const entry=entries.get(file);if(!entry)throw new Error('Unknown character asset: '+file);
   const begin=start+entry.offset;
   const rgba=new Uint8ClampedArray(data.slice(begin,begin+entry.baseLength));
   if(color!==null){
    const index=typeof color==='string'?keys.indexOf(color):color;
    if(index<0||index>3)throw new Error('Unknown palette color');
    const mask=begin+entry.baseLength,codes=mask+entry.maskLength,lut=codes+entry.count*2;
    let k=0;
    for(let p=0;p<entry.width*entry.height;p++)if(data[mask+(p>>3)]&(1<<(p%8))){
     const code=(data[codes+k]|data[codes+k+entry.count]<<8)*12+index*3;
     rgba[p*4]=data[lut+code];rgba[p*4+1]=data[lut+code+1];rgba[p*4+2]=data[lut+code+2];k++;
    }
   }
   const canvas=document.createElement('canvas');canvas.width=entry.width;canvas.height=entry.height;
   canvas.getContext('2d').putImageData(new ImageData(rgba,entry.width,entry.height),0,0);
   const url=canvas.toDataURL('image/png');cache.set(key,url);return url;
  }
 };
 api.ready=(async()=>{
  const bytes=Uint8Array.from(atob(packed),c=>c.charCodeAt(0));
  const stream=new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'));
  data=new Uint8Array(await new Response(stream).arrayBuffer());
  const length=new DataView(data.buffer).getUint32(0);start=4+length;
  entries=new Map(JSON.parse(new TextDecoder().decode(data.subarray(4,start))).map(entry=>[entry.file,entry]));
 })();
 window.PartyPopPalette=api;
})();
